  "a_sentences": [
    {
      "a_text": "Bei einer Neuanmeldung nach vorausgegangener Rentenverweigerung gelten die Grundsätze zur Rentenrevision nach Art. 17 Abs. 1 ATSG analog (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Der ausgeglichene Arbeitsmarkt umfasst auch Nischenarbeitsplätze, bei denen behinderte Personen mit einem sozialen Entgegenkommen des Arbeitgebers rechnen können (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Es besteht ein genügend breites Spektrum an zumutbaren Verweistätigkeiten wie einfache Kontroll-, Überwachungs-, Sortier- und Verpackungstätigkeiten sowie leichte Montagearbeiten, die dem Fähigkeitsprofil des Versicherten entsprechen (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Vorinstanz mass dem SMAB-Gutachten vom 19. April 2024 nach Würdigung der Aktenlage und Auseinandersetzung mit den Einwänden des Versicherten vollen Beweiswert zu (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Das Bundesgericht verneint eine offensichtlich unrichtige Vorgehensweise der Vorinstanz und bestätigt deren Beurteilung (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Vorinstanz hat die Verwertbarkeit der Restarbeitsfähigkeit auf dem ausgeglichenen Arbeitsmarkt folglich zu Recht bejaht (P6).",
      "b_propositions": ["P6"]
    }
  ]
